var e={"term.setting":`Code mode`,"term.settingDesc":`For working on code with Claude: a separate copy per session (its own branch and folder, ended by a pull request that Claude writes and watches), and a terminal under the conversation (Ctrl+J, /terminal) opened in the session's git repositories. The changes of each answer (diff, commit, push, pull request) and the pull request view show without it. Never for agents. Asks for your password to turn on.`,"term.enableTitle":`Turn code mode on`,"term.enableDesc":`Code mode adds a terminal, which runs any command on this server with its rights, and separate copies of a repository for sessions. Type your password to confirm.`,"term.password":`Password`,"term.badPassword":`Wrong password`,"term.enable":`Turn on`,"term.openFailed":`The terminal did not open`,"term.tooMany":`4 terminals are open: close one first`,"term.close":`Close this terminal`,"term.new":`New terminal`,"term.quote":`Send the selection to Claude`,"term.openCount":`{count} open`,"term.openCount#one":`{count} open`,"term.closeAll":`Close all`,"term.hide":`Hide the terminal`,"term.opening":`Opening…`,"term.ended":`[terminal ended]`,"term.topicFolder":`Topic folder`};export{e as default};